-- 04-users-id-otomatis.sql
-- Jalankan SETELAH 03-perbaiki-daftar.sql.
-- Membuat kolom public.users.id terisi otomatis (identity) kalau belum,
-- lalu membuatkan profil untuk semua akun auth yang belum punya profil.

do $$
declare
  mulai bigint;
begin
  if (select attidentity from pg_attribute
      where attrelid = 'public.users'::regclass and attname = 'id') = '' then
    select coalesce(max(id), 0) + 1 into mulai from public.users;
    execute format(
      'alter table public.users alter column id add generated by default as identity (start with %s)',
      mulai);
    raise notice 'Kolom users.id sekarang identity, mulai dari %', mulai;
  else
    raise notice 'Kolom users.id sudah identity, tidak diubah';
  end if;
end;
$$;

-- Buat profil untuk akun yang sudah terdaftar tapi belum punya profil
insert into public.users (auth_user_id, username, email)
select
  u.id,
  coalesce(
    nullif(trim(u.raw_user_meta_data ->> 'username'), ''),
    nullif(trim(u.raw_user_meta_data ->> 'nama'), ''),
    nullif(split_part(coalesce(u.email, ''), '@', 1), ''),
    'user'
  ),
  coalesce(u.email, '')
from auth.users u
on conflict (auth_user_id) do nothing;

-- Cek hasil: setiap akun harus punya profil
select a.email, p.id as profil_id, p.username
from auth.users a
left join public.users p on p.auth_user_id = a.id
order by a.created_at desc;
